const fetchedRows = $('Enrich rows with works_id').all().map((item) => item.json || {});
const existingRows = $('Read ASB_Tracking').all().map((item) => item.json || {});

function rowKey(row) {
  const contractId = String(row.contract_id || '').trim();
  let uprn = String(row.uprn || '').trim();
  if (/^\d+$/.test(uprn)) uprn = String(parseInt(uprn, 10));
  if (!contractId || !uprn) return null;
  return `${contractId}::${uprn}`;
}

const existingKeys = new Set(
  existingRows.map(rowKey).filter((key) => key !== null)
);

const newRows = fetchedRows.filter((row) => {
  const key = rowKey(row);
  return key !== null && !existingKeys.has(key);
});

if (!newRows.length) {
  return [];
}

return newRows.map((row) => ({
  json: {
    ...row,
    skipped_existing: false,
  },
}));

function extractApiBody(resp) {
  const statusCode = resp.statusCode ?? resp.status ?? 0;
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (e) {
      const m = body.match(/\{[\s\S]*\}/);
      if (m) {
        try { body = JSON.parse(m[0]); } catch (e2) { body = {}; }
      } else {
        body = {};
      }
    }
  }
  if (body && typeof body === 'object' && body.body && body.checked === undefined && body.results === undefined && body.properties === undefined) {
    body = body.body;
  }
  return { statusCode, body: body || {} };
}

function normUprn(v) {
  const s = String(v == null ? '' : v).trim();
  return /^\d+$/.test(s) ? String(parseInt(s, 10)) : (s || null);
}

const postItems = $('POST fetch-missing-asbestos').all();
const respRaw = postItems.length ? (postItems[0].json || {}) : ($input.first()?.json || {});
const { body: response } = extractApiBody(respRaw);
const capturedAt = new Date().toISOString();
const properties = Array.isArray(response.properties) ? response.properties : [];

if (!properties.length) {
  return [{
    json: {
      contract_id: response.contract_id || null,
      easybop_row_id: null,
      uprn: null,
      address: null,
      captured_at: capturedAt,
      run_total: response.total ?? 0,
      run_message: response.message || 'No missing asbestos rows found.',
      success: String(response.success ?? false),
    },
  }];
}

return properties.map((row) => ({
  json: {
    contract_id: response.contract_id || null,
    easybop_row_id: row.row_id || null,
    uprn: normUprn(row.uprn),
    address: row.address || null,
    works_id: row.works_id || '',
    captured_at: capturedAt,
    run_total: response.total ?? properties.length,
    run_message: response.message || '',
    success: String(response.success ?? false),
  },
}));

